@sig trait PreferenceRequestQualifier_Api {
  def id: Art.BridgeId
  def preference_Id : Art.PortId
  def candidate_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var candidate: Cabin_Air_Quality_Humidity_Supervisor.QualifiedPreferenceCandidate = $

  def put_candidate(value : Cabin_Air_Quality_Humidity_Supervisor.QualifiedPreferenceCandidate) : Unit = {
    Contract(
      Modifies(candidate),
      Ensures(
        candidate == value
      )
    )
    Spec {
      candidate = value
    }

    Art.putValue(candidate_Id, Cabin_Air_Quality_Humidity_Supervisor.QualifiedPreferenceCandidate_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class PreferenceRequestQualifier_Initialization_Api (
  val id: Art.BridgeId,
  val preference_Id : Art.PortId,
  val candidate_Id : Art.PortId) extends PreferenceRequestQualifier_Api

@datatype class PreferenceRequestQualifier_Operational_Api (
  val id: Art.BridgeId,
  val preference_Id : Art.PortId,
  val candidate_Id : Art.PortId) extends PreferenceRequestQualifier_Api {

  // Logika spec var representing port state for incoming data port
  @spec var preference: Cabin_Air_Quality_Humidity_Supervisor.UserAirPreference = $

  def get_preference() : Option[Cabin_Air_Quality_Humidity_Supervisor.UserAirPreference] = {
    Contract(
      Ensures(
        Res == Some(preference)
      )
    )
    val value : Option[Cabin_Air_Quality_Humidity_Supervisor.UserAirPreference] = Art.getValue(preference_Id) match {
      case Some(Cabin_Air_Quality_Humidity_Supervisor.UserAirPreference_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port preference.  Expecting 'Cabin_Air_Quality_Humidity_Supervisor.UserAirPreference_Payload' but received ${v}")
        None[Cabin_Air_Quality_Humidity_Supervisor.UserAirPreference]()
      case _ => None[Cabin_Air_Quality_Humidity_Supervisor.UserAirPreference]()
    }
    return value
  }
}
